def seed_formats(apps, schema_editor):
    Format = apps.get_model("filesystem", "FileFormat")
    Part = apps.get_model("filesystem", "FormatPart")
    Encoding = apps.get_model("filesystem", "FileEncoding")

    for name, (title, extension, magic) in REAL.items():
        Format.objects.get_or_create(name=name, defaults=dict(title=title, extension=extension, kind="signature", magic=magic))

    for name, title, extension, template in (
        ("rec", "Aether REC (record)", ".rec", REC),
        ("snp", "Aether SNP (page snapshot)", ".snp", SNP),
        ("msg", "Aether MSG (message)", ".msg", MSG),
    ):
        Format.objects.get_or_create(name=name, defaults=dict(title=title, extension=extension, kind="text", template=template))

    scan, made = Format.objects.get_or_create(
        name="scan",
        defaults=dict(title="Aether SCAN (image + OCR text)", extension=".scan", kind="chunks", magic="9e 53 43 41 4e 0d 0a 1b"),
    )
    if made:
        for order, (name, source) in enumerate((("IMG ", "image"), ("OCR ", "body"), ("CONF", "confidence"))):
            Part.objects.create(format=scan, order=order, name=name, source=source)

    doc, made = Format.objects.get_or_create(
        name="doc",
        defaults=dict(title="Aether DOC (package of parts)", extension=".doc", kind="package", magic="d0 0c 44 4f 43 00"),
    )
    if made:
        for order, (name, source, value) in enumerate((
            ("body", "body", ""),
            ("style", "template", "font: serif; size: 11\n"),
            ("meta", "template", "title: {title}\nwhen: {when}\n"),
        )):
            Part.objects.create(format=doc, order=order, name=name, source=source, value=value)

    for name, title, kind, param in ENCODINGS:
        Encoding.objects.get_or_create(name=name, defaults=dict(title=title, kind=kind, param=param))


